 "content": "def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    colors = {v for row in g for v in row}

    # Side bars encode matching horizontal rays; sparse dots specify the rows.
    for bar_color in colors:
        left = [r for r in range(h) if g[r][0] == bar_color]
        right = [r for r in range(h) if g[r][w - 1] == bar_color]
        if not left or not right:
            continue
        # Use contiguous edge runs at opposite sides.
        def longest_run(rows):
            runs, run = [], []
            for r in rows:
                if run and r == run[-1] + 1:
                    run.append(r)
                else:
                    if run: runs.append(run)
                    run = [r]
            if run: runs.append(run)
            return max(runs, key=len)
        L, R = longest_run(left), longest_run(right)
        if len(L) != len(R):
            continue
        dot_colors = [c for c in colors if c != bar_color]
        dots = [(r, c, g[r][c]) for r in range(h) for c in range(1, w-1)
                if g[r][c] in dot_colors]
        # Select the non-bar color(s) occurring as isolated interior pixels.
        counts = {c: sum(g[r][x] == c for r in range(h) for x in range(w)) for c in dot_colors}
        candidates = [c for c in dot_colors if counts[c] <= len(L)]
        if not candidates:
            continue
        ink = min(candidates, key=lambda c: counts[c])
        mark_rows = [r for r in range(h) for c in range(1,w-1) if g[r][c] == ink]
        if not mark_rows:
            continue
        for r in mark_rows:
            if r in L:
                # Rays across the opposite bar, at the corresponding local row offset.
                off = r - L[0]
                rr = R[0] + off if R[0] < L[0] else R[0] + off
                if 0 <= rr < h and rr in R:
                    for c in range(1, w-1):
                        g[rr][c] = ink
                # Extend from the marked edge toward the marker; marker becomes 4.
                pts = [c for c in range(1,w-1) if grid[r][c] == ink]
                if pts:
                    marker = pts[0]
                    edge = 0 if r in L else w-1
                    if g[r][edge] == bar_color:
                        if edge == 0:
                            for c in range(1, marker): g[r][c] = ink
                        else:
                            for c in range(marker+1, w-1): g[r][c] = ink
                        g[r][marker] = 4
        return g

    # Top/bottom edge bars: join the upper bar's inward endpoint to a sparse
    # marker, and extend the lower bar's inward endpoint toward the top.
    for bar_color in colors:
        top = [c for c in range(w) if g[0][c] == bar_color]
        bottom = [c for c in range(w) if g[h-1][c] == bar_color]
        if not top or not bottom:
            continue
        dots = [(r,c,g[r][c]) for r in range(1,h-1) for c in range(w)
                if g[r][c] != bar_color and g[r][c] != max(colors, key=lambda x: sum(v==x for row in g for v in row))]
        if not dots:
            continue
        # Use the sparsest non-background interior color as the line color.
        bg = max(colors, key=lambda x: sum(v == x for row in g for v in row))
        ink = min((x for x in colors if x not in (bar_color,bg)), key=lambda x: sum(v==x for row in g for v in row))
        pts = [(r,c) for r in range(1,h-1) for c in range(w) if g[r][c] == ink]
        if not pts: continue
        r,c = pts[0]
        # The marker's column links to the matching top-bar cell.
        for rr in range(1, r): g[rr][c] = ink
        g[r][c] = 4
        # The lower bar's inward endpoint sends the second vertical ray.
        bc = max(bottom)
        for rr in range(0, h-1): g[rr][bc] = ink
        return g
    return g


